```python
class Solute:
    def __init__(self, name, molar_mass):
        self.name = name
        self.molar_mass = molar_mass

class Solution:
    def __init__(self, solute, moles, volume_ml, density=1.0):
        self.solute = solute
        self.moles = moles
        self.volume_ml = volume_ml
        self.density = density  # g/mL

    @property
    def mass_g(self):
        return self.moles * self.solute.molar_mass

    @property
    def molarity_M(self):
        return self.moles / (self.volume_ml / 1000)

    @property
    def mass_of_solution_g(self):
        return self.mass_g + (self.volume_ml * self.density)

    def mix(self, other):
        if self.solute.name != other.solute.name:
            raise ValueError("Cannot mix different solutes.")
        total_moles = self.moles + other.moles
        total_volume_ml = self.volume_ml + other.volume_ml
        mixed_density = (self.mass_of_solution_g + other.mass_of_solution_g) / total_volume_ml
        return Solution(self.solute, total_moles, total_volume_ml, mixed_density)

    def take_volume(self, volume_ml):
        if volume_ml > self.volume_ml:
            raise ValueError("Volume taken is greater than the available volume.")
        moles_taken = (volume_ml / self.volume_ml) * self.moles
        remaining_moles = self.moles - moles_taken
        remaining_solution = Solution(self.solute, remaining_moles, self.volume_ml - volume_ml, self.density)
        taken_solution = Solution(self.solute, moles_taken, volume_ml, self.density)
        return taken_solution, remaining_solution

def create_mock_exam():
    # 1) Prepare 0.2M NaOH(aq) 40mL.
    naoh = Solute("NaOH", 40.0)
    naoh_solution = Solution(naoh, 0.008, 40)  # 0.008 moles in 40 mL gives 0.2M

    # 2) Take NaOH(aq) 20mL from step 1).
    taken_solution, remaining_solution = naoh_solution.take_volume(20)

    # Print the results for the mock exam
    print(f"Original solution: {naoh_solution.molarity_M:.2f} M NaOH, {naoh_solution.volume_ml:.0f} mL")
    print(f"Taken solution: {taken_solution.molarity_M:.2f} M NaOH, {taken_solution.volume_ml:.0f} mL")
    print(f"Remaining solution: {remaining_solution.molarity_M:.2f} M NaOH, {remaining_solution.volume_ml:.0f} mL")

if __name__ == "__main__":
    create_mock_exam()
```

